import React, { useState, useEffect, useCallback, ReactNode } from 'react';
import { 
  TextField, 
  Button,
  Box,
  Typography,
  CircularProgress,
  IconButton,
  Tabs,
  Tab,
  Paper,
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  FormHelperText,
  Radio,
  FormControlLabel,
  Alert,
  Snackbar
} from '@mui/material';
import RefreshIcon from '@mui/icons-material/Refresh';
import DeleteIcon from '@mui/icons-material/Delete';
import SecurityIcon from '@mui/icons-material/Security';
import { useConfig } from '../contexts/ConfigContext';
import { useRuntime, getCurrentUserId } from '../contexts/RuntimeContext';
import { extractErrorMessage, prepareAuthParams, loadSettings as loadSettingsUtil, getProxyOrigin } from '../utils/apiUtils';

// Brute force protection types
interface BruteForceListItem {
  ip_address: string;
  rule_name: string;
  protocol?: string;
  oidc_cid?: string;
  ttl: number;
  attempts: number;
}

interface AffectedAccount {
  username: string;
  ip_addresses: string[];
}

interface BruteForceListResponse {
  blocked_ips: BruteForceListItem[];
  affected_accounts: AffectedAccount[];
}

// Response from the API
interface BruteForceApiResponse {
  ip_addresses?: {
    [key: string]: string;
  };
  accounts?: {
    [key: string]: string[];
  };
  error: null | string;
}

const BruteForceConfig: React.FC = () => {
  const { config, currentProfileName } = useConfig();
  const { connection: runtimeConnection, loadRuntimeSettings } = useRuntime();
  const [connectionStatus, setConnectionStatus] = useState<'unknown' | 'connected' | 'disconnected' | 'checking'>('unknown');
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [notification, setNotification] = useState<{ open: boolean, message: ReactNode, severity: 'success' | 'error' | 'info' | 'warning' }>({
    open: false,
    message: '',
    severity: 'info'
  });

  // Brute force protection state
  const [tabValue, setTabValue] = useState<number>(0);
  const [bruteForceList, setBruteForceList] = useState<BruteForceListResponse | null>(null);
  const [isLoadingBruteForceList, setIsLoadingBruteForceList] = useState<boolean>(false);
  const [openUserDialog, setOpenUserDialog] = useState<boolean>(false);
  const [openIpDialog, setOpenIpDialog] = useState<boolean>(false);
  const [selectedUser, setSelectedUser] = useState<string>('');
  const [selectedIp, setSelectedIp] = useState<string>('');
  const [selectedRule, setSelectedRule] = useState<string>('*');
  const [selectedProtocol, setSelectedProtocol] = useState<string>('');
  const [selectedOidcCid, setSelectedOidcCid] = useState<string>('');
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [openSearchDialog, setOpenSearchDialog] = useState<boolean>(false);
  const [searchType, setSearchType] = useState<'ip' | 'user'>('ip');
  const [ruleNames, setRuleNames] = useState<string[]>([]);

  // Function to fetch the brute force list
  const fetchBruteForceList = useCallback(async (connectionConfig: any) => {
    if (!connectionConfig.backend_url) {
      setNotification({
        open: true,
        message: 'No backend URL configured',
        severity: 'error'
      });
      return;
    }

    setIsLoadingBruteForceList(true);

    try {
      // Prepare authentication parameters for the proxy
      const { authType, authValue } = prepareAuthParams(connectionConfig);

      // Use the proxy endpoint to make the request server-side
      const proxyUrl = new URL('/proxy/bruteforce/list', getProxyOrigin());
      proxyUrl.searchParams.append('url', connectionConfig.backend_url);

      if (authType && authValue) {
        proxyUrl.searchParams.append('authType', authType);
        proxyUrl.searchParams.append('authValue', authValue);
      }

      const response = await fetch(proxyUrl.toString(), {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        const errorMessage = await extractErrorMessage(response);
        console.error('Error fetching brute force list:', errorMessage);

        // Update the connection status message to show the error
        setStatusMessage(`Failed to fetch brute force list: ${errorMessage}`);

        setBruteForceList(null);
        return;
      }

      const data = await response.json();
      console.log(data);

      // Transform the API response to the expected format
      const transformedData: BruteForceListResponse = {
        blocked_ips: [],
        affected_accounts: []
      };

      // Process the result array
      if (data.result && Array.isArray(data.result)) {
        // Process IP addresses (first item in the result array)
        const ipAddressesResult = data.result[0];
        if (ipAddressesResult && ipAddressesResult.ip_addresses) {
          // Convert the ip_addresses object to an array of BruteForceListItem
          Object.entries(ipAddressesResult.ip_addresses).forEach(([ip, rule]) => {
            transformedData.blocked_ips.push({
              ip_address: ip,
              rule_name: rule as string,
              ttl: 0, // Default values since they're not in the response
              attempts: 0
            });
          });
        }

        // Process accounts (second item in the result array)
        const accountsResult = data.result[1];
        if (accountsResult && accountsResult.accounts) {
          // Convert the accounts object to an array of AffectedAccount
          Object.entries(accountsResult.accounts).forEach(([username, ips]) => {
            transformedData.affected_accounts.push({
              username,
              ip_addresses: Array.isArray(ips) ? ips : []
            });
          });
        }
      }

      setBruteForceList(transformedData);

      // Extract unique rule names from the transformed blocked IPs
      if (transformedData.blocked_ips && transformedData.blocked_ips.length > 0) {
        const apiRuleNames = Array.from(
          new Set(
            transformedData.blocked_ips
              .map((item: BruteForceListItem) => item.rule_name)
              .filter((ruleName: string) => ruleName && ruleName !== '*')
          )
        ) as string[];

        // Get rule names from configuration
        const configRuleNames: string[] = [];
        if (config?.brute_force?.buckets && config.brute_force.buckets.length > 0) {
          config.brute_force.buckets.forEach(bucket => {
            if (bucket.name && bucket.name.trim() !== '') {
              configRuleNames.push(bucket.name);
            }
          });
        }

        // Merge rule names from API and configuration, removing duplicates
        const mergedRuleNames = Array.from(new Set([...apiRuleNames, ...configRuleNames]));
        setRuleNames(mergedRuleNames);
      } else if (config?.brute_force?.buckets && config.brute_force.buckets.length > 0) {
        // If no API data, still use configuration rule names
        const configRuleNames = config.brute_force.buckets
          .map(bucket => bucket.name)
          .filter(name => name && name.trim() !== '');

        if (configRuleNames.length > 0) {
          setRuleNames(configRuleNames);
        }
      }

      setNotification({
        open: true,
        message: 'Brute force list fetched successfully',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error fetching brute force list:', error);

      // Update the connection status message to show the error
      const errorMessage = error instanceof Error ? error.message : String(error);
      setStatusMessage(`Failed to fetch brute force list: ${errorMessage}`);

      setBruteForceList(null);
    } finally {
      setIsLoadingBruteForceList(false);
    }
  }, [config, setNotification, setBruteForceList, setRuleNames, setIsLoadingBruteForceList, setStatusMessage]);

  // Function to check connection to the backend
  const checkConnection = useCallback(async (connectionConfig: any) => {
    if (!connectionConfig.backend_url) {
      setConnectionStatus('unknown');
      setStatusMessage('No backend URL configured');
      return;
    }

    setConnectionStatus('checking');
    setStatusMessage('Checking connection...');

    try {
      // Use the proxy endpoint to make the request server-side
      // This avoids CORS issues by making the request through Node.js
      const proxyUrl = new URL('/proxy/ping', getProxyOrigin());
      proxyUrl.searchParams.append('url', connectionConfig.backend_url);

      const response = await fetch(proxyUrl.toString(), {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (response.ok) {
        setConnectionStatus('connected');
        setStatusMessage('Connected to Nauthilus backend (ping successful)');

        // Fetch the brute force list if the connection is successful
        await fetchBruteForceList(connectionConfig);
      } else {
        setConnectionStatus('disconnected');
        const errorMessage = await extractErrorMessage(response);
        setStatusMessage(`Failed to connect: ${errorMessage}`);
      }
    } catch (error) {
      console.error('Error checking connection:', error);
      setConnectionStatus('disconnected');
      setStatusMessage(`Connection error: ${error instanceof Error ? error.message : String(error)}`);
    }
  }, [setConnectionStatus, setStatusMessage, fetchBruteForceList]);

  // Memoize the function that returns runtimeConnection to avoid infinite loops
  const getRuntimeConnection = useCallback(() => runtimeConnection, [runtimeConnection]);

  // Check connection status and load runtime settings when the component mounts
  useEffect(() => {
    (async () => {
      await loadSettingsUtil(
        getCurrentUserId,
        loadRuntimeSettings,
        currentProfileName,
        checkConnection,
        getRuntimeConnection
      );
    })();

    // Extract rule names from brute force buckets in the configuration
    if (config?.brute_force?.buckets && config.brute_force.buckets.length > 0) {
      const configRuleNames = config.brute_force.buckets
        .map(bucket => bucket.name)
        .filter(name => name && name.trim() !== '');

      if (configRuleNames.length > 0) {
        setRuleNames(configRuleNames);
      }
    }
  }, [config, checkConnection, loadRuntimeSettings, currentProfileName, getRuntimeConnection]);

  // Function to free user by account
  const freeUserByAccount = async (connectionConfig: any, username: string) => {
    if (!connectionConfig.backend_url) {
      setNotification({
        open: true,
        message: 'No backend URL configured',
        severity: 'error'
      });
      return;
    }

    setIsProcessing(true);

    try {
      // Prepare authentication parameters for the proxy
      const { authType, authValue } = prepareAuthParams(connectionConfig);

      // Use the proxy endpoint to make the request server-side
      const proxyUrl = new URL('/proxy/cache/flush', getProxyOrigin());
      proxyUrl.searchParams.append('url', connectionConfig.backend_url);

      if (authType && authValue) {
        proxyUrl.searchParams.append('authType', authType);
        proxyUrl.searchParams.append('authValue', authValue);
      }

      const response = await fetch(proxyUrl.toString(), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ user: username }),
      });

      if (!response.ok) {
        const errorMessage = await extractErrorMessage(response);
        console.error('Error freeing user by account:', errorMessage);
        setNotification({
          open: true,
          message: `Failed to free user ${username}: ${errorMessage}`,
          severity: 'error'
        });
        return;
      }

      await response.json(); // Response processed but not needed

      setNotification({
        open: true,
        message: `User ${username} freed from brute force protection successfully`,
        severity: 'success'
      });

      // Refresh the brute force list
      await fetchBruteForceList(connectionConfig);
    } catch (error) {
      console.error('Error freeing user by account:', error);
      setNotification({
        open: true,
        message: `Failed to free user ${username}: ${error instanceof Error ? error.message : String(error)}`,
        severity: 'error'
      });
    } finally {
      setIsProcessing(false);
      setOpenUserDialog(false);
    }
  };

  // Function to free user by IP address
  const freeUserByIp = async (connectionConfig: any, ipAddress: string, ruleName: string, protocol?: string, oidcCid?: string) => {
    if (!connectionConfig.backend_url) {
      setNotification({
        open: true,
        message: 'No backend URL configured',
        severity: 'error'
      });
      return;
    }

    setIsProcessing(true);

    try {
      // Prepare authentication parameters for the proxy
      const { authType, authValue } = prepareAuthParams(connectionConfig);

      // Use the proxy endpoint to make the request server-side
      const proxyUrl = new URL('/proxy/bruteforce/flush', getProxyOrigin());
      proxyUrl.searchParams.append('url', connectionConfig.backend_url);

      if (authType && authValue) {
        proxyUrl.searchParams.append('authType', authType);
        proxyUrl.searchParams.append('authValue', authValue);
      }

      // Prepare the request body
      const requestBody: any = {
        ip_address: ipAddress,
        rule_name: ruleName
      };

      // Add optional parameters if provided
      if (protocol) {
        requestBody.protocol = protocol;
      }

      if (oidcCid) {
        requestBody.oidc_cid = oidcCid;
      }

      const response = await fetch(proxyUrl.toString(), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestBody),
      });

      if (!response.ok) {
        const errorMessage = await extractErrorMessage(response);
        console.error('Error freeing user by IP address:', errorMessage);
        setNotification({
          open: true,
          message: `Failed to free IP ${ipAddress}: ${errorMessage}`,
          severity: 'error'
        });
        return;
      }

      await response.json(); // Response processed but not needed

      setNotification({
        open: true,
        message: `IP address ${ipAddress} freed from brute force protection successfully`,
        severity: 'success'
      });

      // Refresh the brute force list
      await fetchBruteForceList(connectionConfig);
    } catch (error) {
      console.error('Error freeing user by IP address:', error);
      setNotification({
        open: true,
        message: `Failed to free IP ${ipAddress}: ${error instanceof Error ? error.message : String(error)}`,
        severity: 'error'
      });
    } finally {
      setIsProcessing(false);
      setOpenIpDialog(false);
    }
  };

  // Function to handle tab change
  const handleTabChange = (_event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  // Function to open a user dialog
  const handleOpenUserDialog = (username: string) => {
    setSelectedUser(username);
    setOpenUserDialog(true);
  };

  // Function to open an IP dialog
  const handleOpenIpDialog = (ipAddress: string, ruleName: string = '*', protocol: string = '', oidcCid: string = '') => {
    setSelectedIp(ipAddress);
    setSelectedRule(ruleName);
    setSelectedProtocol(protocol);
    setSelectedOidcCid(oidcCid);
    setOpenIpDialog(true);
  };

  // Check if we have a valid connection configuration
  const hasValidConnection = runtimeConnection?.backend_url;

  return (
    <>
      {!hasValidConnection && (
        <Alert severity="warning" sx={{ mb: 3 }}>
          Brute-Force Management is not available because there is no valid connection configured. 
          Please configure a connection in the Connection menu first.
        </Alert>
      )}

      <Paper sx={{ p: 3 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <SecurityIcon sx={{ mr: 1, color: 'primary.main' }} />
          <Typography variant="h6">Brute Force Protection Management</Typography>
        </Box>

        {connectionStatus === 'connected' ? (
          <>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="body1">
                Manage brute force protection for users and IP addresses.
              </Typography>
              <Box>
                <Button 
                  variant="outlined" 
                  color="secondary"
                  onClick={() => setOpenSearchDialog(true)}
                  sx={{ mr: 1 }}
                >
                  Search & Free
                </Button>
                <Button 
                  variant="outlined" 
                  color="primary"
                  onClick={() => fetchBruteForceList(runtimeConnection)}
                  disabled={isLoadingBruteForceList}
                  startIcon={isLoadingBruteForceList ? <CircularProgress size={20} /> : <RefreshIcon />}
                >
                  {isLoadingBruteForceList ? 'Loading...' : 'Refresh List'}
                </Button>
              </Box>
            </Box>

            {/* Search Box */}
            <Box sx={{ mb: 2 }}>
              <TextField
                fullWidth
                variant="outlined"
                size="small"
                placeholder="Search by IP address or username..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                InputProps={{
                  endAdornment: searchTerm && (
                    <IconButton size="small" onClick={() => setSearchTerm('')}>
                      <DeleteIcon fontSize="small" />
                    </IconButton>
                  ),
                }}
              />
            </Box>

            <Tabs value={tabValue} onChange={handleTabChange} sx={{ borderBottom: 1, borderColor: 'divider' }}>
              <Tab label="Blocked IP Addresses" />
              <Tab label="Affected Accounts" />
            </Tabs>

            {/* Blocked IP Addresses Tab */}
            {tabValue === 0 && (
              <Box sx={{ mt: 2 }}>
                {isLoadingBruteForceList ? (
                  <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
                    <CircularProgress />
                  </Box>
                ) : bruteForceList && bruteForceList.blocked_ips && bruteForceList.blocked_ips.length > 0 ? (
                  <List>
                    {bruteForceList.blocked_ips
                      .filter(item => 
                        !searchTerm || 
                        item.ip_address.toLowerCase().includes(searchTerm.toLowerCase()) ||
                        item.rule_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                        (item.protocol && item.protocol.toLowerCase().includes(searchTerm.toLowerCase())) ||
                        (item.oidc_cid && item.oidc_cid.toLowerCase().includes(searchTerm.toLowerCase()))
                      )
                      .map((item, index) => (
                      <ListItem key={index} divider>
                        <ListItemText
                          primary={item.ip_address}
                          secondary={
                            <>
                              <Typography component="span" variant="body2">
                                Rule: {item.rule_name}
                                {item.protocol && ` | Protocol: ${item.protocol}`}
                                {item.oidc_cid && ` | OIDC Client ID: ${item.oidc_cid}`}
                              </Typography>
                              <br />
                              <Typography component="span" variant="body2">
                                TTL: {item.ttl} seconds | Attempts: {item.attempts}
                              </Typography>
                            </>
                          }
                        />
                        <ListItemSecondaryAction>
                          <Button
                            variant="outlined"
                            color="secondary"
                            onClick={() => handleOpenIpDialog(item.ip_address, item.rule_name, item.protocol, item.oidc_cid)}
                            startIcon={<DeleteIcon />}
                          >
                            Free
                          </Button>
                        </ListItemSecondaryAction>
                      </ListItem>
                    ))}
                  </List>
                ) : (
                  <Box sx={{ p: 3, textAlign: 'center' }}>
                    <Typography variant="body1" color="text.secondary">
                      {bruteForceList === null 
                        ? 'Click "Refresh List" to load blocked IP addresses' 
                        : 'No blocked IP addresses found'}
                    </Typography>
                  </Box>
                )}
              </Box>
            )}

            {/* Affected Accounts Tab */}
            {tabValue === 1 && (
              <Box sx={{ mt: 2 }}>
                {isLoadingBruteForceList ? (
                  <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
                    <CircularProgress />
                  </Box>
                ) : bruteForceList && bruteForceList.affected_accounts && bruteForceList.affected_accounts.length > 0 ? (
                  <List>
                    {bruteForceList.affected_accounts
                      .filter(account => 
                        !searchTerm || 
                        account.username.toLowerCase().includes(searchTerm.toLowerCase()) ||
                        account.ip_addresses.some(ip => ip.toLowerCase().includes(searchTerm.toLowerCase()))
                      )
                      .map((account, index) => (
                      <ListItem key={index} divider>
                        <ListItemText
                          primary={account.username}
                          secondary={
                            <>
                              <Typography component="span" variant="body2">
                                Associated IP Addresses: {account.ip_addresses.join(', ')}
                              </Typography>
                            </>
                          }
                        />
                        <ListItemSecondaryAction>
                          <Button
                            variant="outlined"
                            color="secondary"
                            onClick={() => handleOpenUserDialog(account.username)}
                            startIcon={<DeleteIcon />}
                          >
                            Free
                          </Button>
                        </ListItemSecondaryAction>
                      </ListItem>
                    ))}
                  </List>
                ) : (
                  <Box sx={{ p: 3, textAlign: 'center' }}>
                    <Typography variant="body1" color="text.secondary">
                      {bruteForceList === null 
                        ? 'Click "Refresh List" to load affected accounts' 
                        : 'No affected accounts found'}
                    </Typography>
                  </Box>
                )}
              </Box>
            )}
          </>
        ) : (
          <Box sx={{ p: 3, textAlign: 'center' }}>
            <Typography variant="body1" color="text.secondary">
              {connectionStatus === 'checking' ? (
                <>
                  <CircularProgress size={20} sx={{ mr: 1, verticalAlign: 'middle' }} />
                  Checking connection...
                </>
              ) : connectionStatus === 'disconnected' ? (
                <>
                  Connection to backend failed: {statusMessage}
                </>
              ) : (
                <>
                  Not connected to backend. Please check your connection settings.
                </>
              )}
            </Typography>
            {connectionStatus !== 'checking' && hasValidConnection && (
              <Button 
                variant="outlined" 
                color="primary"
                onClick={() => checkConnection(runtimeConnection)}
                sx={{ mt: 2 }}
                startIcon={<RefreshIcon />}
              >
                Check Connection
              </Button>
            )}
          </Box>
        )}
      </Paper>

      {/* User Free Dialog */}
      <Dialog
        open={openUserDialog}
        onClose={() => !isProcessing && setOpenUserDialog(false)}
        aria-labelledby="user-dialog-title"
      >
        <DialogTitle id="user-dialog-title">Free User from Brute Force Protection</DialogTitle>
        <DialogContent>
          <Typography variant="body1" sx={{ mb: 2 }}>
            Are you sure you want to free the user <strong>{selectedUser}</strong> from brute force protection?
          </Typography>
          <Typography variant="body2" color="text.secondary">
            This will remove all brute force protection for this user, including all IP addresses associated with the user.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={() => !isProcessing && setOpenUserDialog(false)} 
            color="primary"
            disabled={isProcessing}
          >
            Cancel
          </Button>
          <Button 
            onClick={() => freeUserByAccount(runtimeConnection, selectedUser)}
            color="secondary" 
            variant="contained"
            disabled={isProcessing}
            startIcon={isProcessing ? <CircularProgress size={20} /> : null}
          >
            {isProcessing ? 'Processing...' : 'Free User'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Search and Free Dialog */}
      <Dialog
        open={openSearchDialog}
        onClose={() => setOpenSearchDialog(false)}
        aria-labelledby="search-dialog-title"
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle id="search-dialog-title">Search and Free from Brute Force Protection</DialogTitle>
        <DialogContent>
          <Typography variant="body1" sx={{ mb: 2 }}>
            Search for a specific user or IP address and free them from brute force protection.
          </Typography>

          <FormControl component="fieldset" sx={{ mb: 2 }}>
            <Typography variant="subtitle2">Search Type</Typography>
            <Box sx={{ display: 'flex', mt: 1 }}>
              <FormControlLabel
                control={
                  <Radio
                    checked={searchType === 'user'}
                    onChange={() => setSearchType('user')}
                    value="user"
                  />
                }
                label="User Account"
              />
              <FormControlLabel
                control={
                  <Radio
                    checked={searchType === 'ip'}
                    onChange={() => setSearchType('ip')}
                    value="ip"
                  />
                }
                label="IP Address"
              />
            </Box>
          </FormControl>

          {searchType === 'user' ? (
            <TextField
              fullWidth
              label="Username"
              value={selectedUser}
              onChange={(e) => setSelectedUser(e.target.value)}
              margin="normal"
              helperText="Enter the username to free from brute force protection"
            />
          ) : (
            <>
              <TextField
                fullWidth
                label="IP Address"
                value={selectedIp}
                onChange={(e) => setSelectedIp(e.target.value)}
                margin="normal"
                helperText="Enter the IP address to free from brute force protection"
              />

              <FormControl fullWidth sx={{ mt: 2, mb: 1 }}>
                <InputLabel id="rule-name-label">Rule Name</InputLabel>
                <Select
                  labelId="rule-name-label"
                  value={selectedRule}
                  onChange={(e) => setSelectedRule(e.target.value)}
                  label="Rule Name"
                >
                  <MenuItem value="*">All Rules (*)</MenuItem>
                  {ruleNames.map((ruleName) => (
                    <MenuItem key={ruleName} value={ruleName}>
                      {ruleName}
                    </MenuItem>
                  ))}
                </Select>
                <FormHelperText>Select "*" to free the IP from all rules</FormHelperText>
              </FormControl>

              <TextField
                fullWidth
                label="Protocol (Optional)"
                value={selectedProtocol}
                onChange={(e) => setSelectedProtocol(e.target.value)}
                margin="normal"
                helperText="Leave empty to free the IP regardless of protocol"
              />

              <TextField
                fullWidth
                label="OIDC Client ID (Optional)"
                value={selectedOidcCid}
                onChange={(e) => setSelectedOidcCid(e.target.value)}
                margin="normal"
                helperText="Leave empty to free the IP regardless of OIDC Client ID"
              />
            </>
          )}
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={() => setOpenSearchDialog(false)} 
            color="primary"
          >
            Cancel
          </Button>
          <Button 
            onClick={() => {
              setOpenSearchDialog(false);
              if (searchType === 'user' && selectedUser) {
                setOpenUserDialog(true);
              } else if (searchType === 'ip' && selectedIp) {
                setOpenIpDialog(true);
              }
            }} 
            color="secondary" 
            variant="contained"
            disabled={searchType === 'user' ? !selectedUser : !selectedIp}
          >
            Continue
          </Button>
        </DialogActions>
      </Dialog>

      {/* IP Free Dialog */}
      <Dialog
        open={openIpDialog}
        onClose={() => !isProcessing && setOpenIpDialog(false)}
        aria-labelledby="ip-dialog-title"
      >
        <DialogTitle id="ip-dialog-title">Free IP Address from Brute Force Protection</DialogTitle>
        <DialogContent>
          <Typography variant="body1" sx={{ mb: 2 }}>
            Are you sure you want to free the IP address <strong>{selectedIp}</strong> from brute force protection?
          </Typography>

          <FormControl fullWidth sx={{ mt: 2, mb: 1 }}>
            <InputLabel id="rule-name-label">Rule Name</InputLabel>
            <Select
              labelId="rule-name-label"
              value={selectedRule}
              onChange={(e) => setSelectedRule(e.target.value)}
              label="Rule Name"
              disabled={isProcessing}
            >
              <MenuItem value="*">All Rules (*)</MenuItem>
              {ruleNames.map((ruleName) => (
                <MenuItem key={ruleName} value={ruleName}>
                  {ruleName}
                </MenuItem>
              ))}
            </Select>
            <FormHelperText>Select "*" to free the IP from all rules</FormHelperText>
          </FormControl>

          <TextField
            fullWidth
            label="Protocol (Optional)"
            value={selectedProtocol}
            onChange={(e) => setSelectedProtocol(e.target.value)}
            margin="normal"
            disabled={isProcessing}
            helperText="Leave empty to free the IP regardless of protocol"
          />

          <TextField
            fullWidth
            label="OIDC Client ID (Optional)"
            value={selectedOidcCid}
            onChange={(e) => setSelectedOidcCid(e.target.value)}
            margin="normal"
            disabled={isProcessing}
            helperText="Leave empty to free the IP regardless of OIDC Client ID"
          />
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={() => !isProcessing && setOpenIpDialog(false)} 
            color="primary"
            disabled={isProcessing}
          >
            Cancel
          </Button>
          <Button 
            onClick={() => freeUserByIp(runtimeConnection, selectedIp, selectedRule, selectedProtocol || undefined, selectedOidcCid || undefined)}
            color="secondary" 
            variant="contained"
            disabled={isProcessing}
            startIcon={isProcessing ? <CircularProgress size={20} /> : null}
          >
            {isProcessing ? 'Processing...' : 'Free IP Address'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar for displaying notifications */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={() => setNotification({ ...notification, open: false })}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert
          onClose={() => setNotification({ ...notification, open: false })}
          severity={notification.severity}
          sx={{ width: '100%' }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </>
  );
};

export default BruteForceConfig;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Box, 
  Button, 
  TextField, 
  Typography, 
  Paper, 
  CircularProgress,
  Alert,
  Tabs,
  Tab,
} from '@mui/material';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import { useUser } from '../contexts/UserContext';
import * as mfaUtils from '../utils/mfaUtils';

const MFAPage = (): React.JSX.Element => {
  const { auth, completeMfaLogin } = useAuth();
  const { loginAfterMfa } = useUser();
  const navigate = useNavigate();
  const [rememberMe, setRememberMe] = useState(false);

  // MFA states
  const [mfaMethod, setMfaMethod] = useState<'totp' | 'webauthn'>('totp');
  const [totpToken, setTotpToken] = useState('');
  const [totpDigits, setTotpDigits] = useState(['', '', '', '', '', '']);
  const [totpError, setTotpError] = useState('');
  const [webAuthnError, setWebAuthnError] = useState('');
  const [mfaLoading, setMfaLoading] = useState(false);
  const [currentUser, setCurrentUser] = useState<any>(null);

  // Redirect to login if MFA is not required
  useEffect(() => {
    if (!auth.mfaRequired) {
      navigate('/login');
    }
  }, [auth.mfaRequired, navigate]);

  // Redirect to home if already authenticated
  useEffect(() => {
    if (auth.isAuthenticated) {
      navigate('/');
    }
  }, [auth.isAuthenticated, navigate]);

  // Initialize MFA when component mounts
  useEffect(() => {
    if (auth.mfaRequired) {
      // Create a minimal user object for MFA verification
      const mfaUser = {
        username: auth.username,
        mfaType: auth.mfaType
      };

      // Store the user for MFA verification
      setCurrentUser(mfaUser);

      // Determine which MFA method to show based on the auth state
      if (auth.mfaType === 'webauthn') {
        setMfaMethod('webauthn');

        // If WebAuthn is enabled, trigger it automatically
        setTimeout(() => {
          handleWebAuthnLogin();
        }, 500);
      } else if (auth.mfaType === 'totp') {
        setMfaMethod('totp');
      }
    }
  }, [auth.mfaRequired, auth.mfaType, auth.username]);

  // Handle TOTP verification
  const handleTotpVerify = useCallback(async () => {
    if (!currentUser || !totpToken) {
      console.log('Missing currentUser or totpToken', { currentUser, totpToken });
      return;
    }

    console.log('Starting TOTP verification for user:', currentUser.username);
    setMfaLoading(true);
    setTotpError('');

    try {
      console.log('Calling verifyTOTP with:', currentUser.username, totpToken);
      const success = await mfaUtils.verifyTOTP(currentUser.username, totpToken);
      console.log('TOTP verification result:', success);

      if (success) {
        console.log('TOTP verification successful, completing MFA login');
        // Complete the login process using the completeMfaLogin method
        const result = await completeMfaLogin(currentUser.username, rememberMe);
        console.log('completeMfaLogin result:', result);

        // Only navigate if we got a valid result
        if (result) {
          // Also update UserContext to ensure both contexts are in sync
          await loginAfterMfa(currentUser.username);
          console.log('Valid result from completeMfaLogin, navigating to home page');
          navigate('/');
        } else {
          console.error('Invalid result from completeMfaLogin, not navigating');
          setTotpError('Failed to complete authentication. Please try again.');
        }
      } else {
        console.log('TOTP verification failed');
        setTotpError('Invalid verification code. Please try again.');
      }
    } catch (error) {
      console.error('TOTP verification error:', error);
      setTotpError('Failed to verify code. Please try again.');
    } finally {
      setMfaLoading(false);
    }
  }, [currentUser, totpToken, completeMfaLogin, rememberMe, navigate]);

  // Handle WebAuthn login
  const handleWebAuthnLogin = useCallback(async () => {
    if (!currentUser) {
      console.log('Missing currentUser for WebAuthn login');
      return;
    }

    console.log('Starting WebAuthn login for user:', currentUser.username);
    setMfaLoading(true);
    setWebAuthnError('');

    try {
      // Start WebAuthn login
      console.log('Calling beginWebAuthnLogin');
      const options = await mfaUtils.beginWebAuthnLogin(currentUser.username);
      console.log('WebAuthn options received:', options);

      // Get credential
      console.log('Requesting credential from browser');
      const credential = await navigator.credentials.get({
        publicKey: options
      }) as PublicKeyCredential;
      console.log('Credential received from browser');

      // Finish WebAuthn login
      console.log('Calling finishWebAuthnLogin');
      const success = await mfaUtils.finishWebAuthnLogin(credential);
      console.log('WebAuthn login result:', success);

      if (success) {
        console.log('WebAuthn verification successful, completing MFA login');
        // Complete the login process using the completeMfaLogin method
        const result = await completeMfaLogin(currentUser.username, rememberMe);
        console.log('completeMfaLogin result:', result);

        // Only navigate if we got a valid result
        if (result) {
          // Also update UserContext to ensure both contexts are in sync
          await loginAfterMfa(currentUser.username);
          console.log('Valid result from completeMfaLogin, navigating to home page');
          navigate('/');
        } else {
          console.error('Invalid result from completeMfaLogin, not navigating');
          setWebAuthnError('Failed to complete authentication. Please try again.');
        }
      } else {
        console.log('WebAuthn verification failed');
        setWebAuthnError('Authentication failed. Please try again.');
      }
    } catch (error) {
      console.error('WebAuthn login error:', error);
      setWebAuthnError('Authentication failed. Please try again.');
    } finally {
      setMfaLoading(false);
    }
  }, [currentUser, completeMfaLogin, rememberMe, navigate]);

  // Handle TOTP digit input
  const handleTotpDigitChange = (index: number, value: string) => {
    // Only allow digits
    if (value && !/^\d+$/.test(value)) {
      return;
    }

    // Update the digit at the specified index
    const newDigits = [...totpDigits];
    newDigits[index] = value;
    setTotpDigits(newDigits);

    // Combine all digits to form the TOTP token
    const newToken = newDigits.join('');
    setTotpToken(newToken);

    // Auto-focus next input if a digit was entered
    if (value && index < 5) {
      const nextInput = document.getElementById(`totp-digit-${index + 1}`);
      if (nextInput) {
        nextInput.focus();
      }
    }
  };

  // Handle keydown events for TOTP digit inputs
  const handleTotpDigitKeyDown = (index: number, e: React.KeyboardEvent<HTMLDivElement>) => {
    // Handle backspace
    if (e.key === 'Backspace' || e.key === 'Delete') {
      if (totpDigits[index] === '' && index > 0) {
        // If current field is empty and backspace is pressed, move to previous field
        const prevInput = document.getElementById(`totp-digit-${index - 1}`);
        if (prevInput) {
          prevInput.focus();
        }
      }
    } else if (e.key === 'ArrowLeft' && index > 0) {
      // Move to previous field on left arrow
      const prevInput = document.getElementById(`totp-digit-${index - 1}`);
      if (prevInput) {
        prevInput.focus();
      }
    } else if (e.key === 'ArrowRight' && index < 5) {
      // Move to next field on right arrow
      const nextInput = document.getElementById(`totp-digit-${index + 1}`);
      if (nextInput) {
        nextInput.focus();
      }
    }
  };

  // Handle paste events for TOTP digit inputs
  const handleTotpDigitPaste = (index: number, e: React.ClipboardEvent<HTMLDivElement>) => {
    e.preventDefault();
    const pastedData = e.clipboardData.getData('text');

    // Filter out non-digit characters
    const digits = pastedData.replace(/\D/g, '').split('').slice(0, 6);

    if (digits.length > 0) {
      // Create a new array with the pasted digits
      const newDigits = [...totpDigits];

      // Fill in the digits starting from the current index
      for (let i = 0; i < digits.length && index + i < 6; i++) {
        newDigits[index + i] = digits[i];
      }

      setTotpDigits(newDigits);

      // Combine all digits to form the TOTP token
      const newToken = newDigits.join('');
      setTotpToken(newToken);

      // Focus the next empty field or the last field if all are filled
      const nextEmptyIndex = newDigits.findIndex((digit, idx) => digit === '' && idx >= index);
      if (nextEmptyIndex !== -1 && nextEmptyIndex < 6) {
        const nextInput = document.getElementById(`totp-digit-${nextEmptyIndex}`);
        if (nextInput) {
          nextInput.focus();
        }
      } else {
        // If all fields are filled or no empty field after current index, focus the last field
        const lastFilledIndex = Math.min(index + digits.length - 1, 5);
        const lastInput = document.getElementById(`totp-digit-${lastFilledIndex}`);
        if (lastInput) {
          lastInput.focus();
        }
      }
    }
  };

  return (
    <Box
      sx={{
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: '100vh',
        bgcolor: 'background.default',
      }}
    >
      <Box
        component="img"
        src="/img/logo.png"
        alt="Nauthilus Logo"
        sx={{
          width: 200,
          mb: 4
        }}
      />
      <Paper
        elevation={3}
        sx={{
          p: 4,
          maxWidth: 400,
          width: '100%',
        }}
      >
        <Typography variant="h4" component="h1" gutterBottom align="center">
          Two-Factor Authentication
        </Typography>

        <Tabs
          value={mfaMethod}
          onChange={(e, newValue) => setMfaMethod(newValue)}
          indicatorColor="primary"
          textColor="primary"
          centered
          sx={{ mb: 2 }}
        >
          {currentUser?.totpEnabled && (
            <Tab label="Authenticator App" value="totp" />
          )}
          {currentUser?.webAuthnEnabled && (
            <Tab label="Security Key" value="webauthn" />
          )}
        </Tabs>

        {/* TOTP Verification */}
        {mfaMethod === 'totp' && (
          <Box sx={{ p: 2 }}>
            <Typography variant="body1" paragraph align="center">
              Enter the verification code from your authenticator app:
            </Typography>

            {/* 6 individual input fields for TOTP code */}
            <Box 
              sx={{ 
                display: 'flex', 
                justifyContent: 'center', 
                gap: 1,
                mb: 3
              }}
            >
              {totpDigits.map((digit, index) => (
                <TextField
                  key={index}
                  id={`totp-digit-${index}`}
                  variant="outlined"
                  inputProps={{ 
                    maxLength: 1,
                    inputMode: 'numeric',
                    style: { 
                      textAlign: 'center',
                      fontSize: '1.5rem',
                      padding: '10px',
                      width: '20px'
                    }
                  }}
                  value={digit}
                  onChange={(e) => handleTotpDigitChange(index, e.target.value)}
                  onKeyDown={(e) => handleTotpDigitKeyDown(index, e)}
                  onPaste={(e) => handleTotpDigitPaste(index, e)}
                  disabled={mfaLoading}
                  autoFocus={index === 0}
                  sx={{ width: '50px' }}
                />
              ))}
            </Box>

            {totpError && (
              <Alert severity="error" sx={{ mt: 2, mb: 2 }}>
                {totpError}
              </Alert>
            )}

            <Button
              onClick={handleTotpVerify}
              color="primary"
              variant="contained"
              fullWidth
              size="large"
              disabled={totpToken.length !== 6 || mfaLoading}
              sx={{ mt: 2 }}
            >
              {mfaLoading ? <CircularProgress size={24} /> : 'Verify'}
            </Button>
          </Box>
        )}

        {/* WebAuthn */}
        {mfaMethod === 'webauthn' && (
          <Box sx={{ p: 2 }}>
            <Typography variant="body1" paragraph align="center">
              Please insert your security key and follow your browser's instructions.
            </Typography>
            {webAuthnError && (
              <Alert severity="error" sx={{ mt: 2, mb: 2 }}>
                {webAuthnError}
              </Alert>
            )}
            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2, mb: 2 }}>
              {mfaLoading && <CircularProgress />}
            </Box>

            <Button
              onClick={handleWebAuthnLogin}
              color="primary"
              variant="contained"
              fullWidth
              size="large"
              disabled={mfaLoading}
              sx={{ mt: 2 }}
            >
              Try Again
            </Button>
          </Box>
        )}
      </Paper>
    </Box>
  );
};

export default MFAPage;
